const today = new Date().toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Summary stats
const summaryRows = $('Get Status Summary').all().map(i => i.json);
const needsCallRows = $('Get Contacts Needing Call').all().map(i => i.json);
const pendingRows = $('Get Pending Contacts').all().map(i => i.json);

// Build summary table rows
const summaryHtml = summaryRows.map(r => {
  const icon = {
    new: '🆕', emailed: '📧', replied: '💬', no_response: '🔇', 
    call_done: '✅', closed: '🏁'
  }[r.status] || '❓';
  return `<tr><td>${icon} ${r.status}</td><td><b>${r.count}</b></td></tr>`;
}).join('');

// Build call checklist
const callListHtml = needsCallRows.length === 0 
  ? '<p style="color:green">✅ No calls pending!</p>'
  : needsCallRows.map(c => {
      const statusBadge = c.replied 
        ? `<span style="background:#d4edda;color:#155724;padding:2px 6px;border-radius:3px">REPLIED</span>` 
        : `<span style="background:#fff3cd;color:#856404;padding:2px 6px;border-radius:3px">NO RESPONSE</span>`;
      return `
        <tr>
          <td>☐</td>
          <td><b>${c.first_name} ${c.last_name}</b><br/><small>${c.title || ''}</small></td>
          <td>${c.company}</td>
          <td><a href="mailto:${c.email}">${c.email}</a></td>
          <td>${c.phone || '-'}</td>
          <td>${statusBadge}</td>
          <td>${c.replied_at ? new Date(c.replied_at).toLocaleDateString() : '-'}</td>
        </tr>`;
    }).join('');

// Build pending table
const pendingHtml = pendingRows.length === 0
  ? '<p>No pending contacts.</p>'
  : pendingRows.map(c => {
      const daysSince = c.last_email_sent_at 
        ? Math.floor((Date.now() - new Date(c.last_email_sent_at)) / 86400000)
        : null;
      return `
        <tr>
          <td>${c.first_name} ${c.last_name}</td>
          <td>${c.company}</td>
          <td>${c.status}</td>
          <td>${c.follow_up_count}/3</td>
          <td>${daysSince !== null ? daysSince + ' days ago' : 'Not sent'}</td>
        </tr>`;
    }).join('');

const html = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: Arial, sans-serif; color: #333; max-width: 900px; margin: 0 auto; }
  h1 { color: #1a73e8; }
  h2 { color: #444; border-bottom: 2px solid #eee; padding-bottom: 6px; }
  table { border-collapse: collapse; width: 100%; margin-bottom: 20px; }
  th { background: #1a73e8; color: white; padding: 8px 12px; text-align: left; }
  td { padding: 8px 12px; border-bottom: 1px solid #eee; }
  tr:hover { background: #f9f9f9; }
  .badge-green { background:#d4edda; color:#155724; padding:3px 8px; border-radius:4px; font-size:12px; }
  .badge-yellow { background:#fff3cd; color:#856404; padding:3px 8px; border-radius:4px; font-size:12px; }
</style>
</head>
<body>
<h1>📋 Daily Outreach Report — ${today}</h1>

<h2>📊 Overall Status</h2>
<table>
  <tr><th>Status</th><th>Count</th></tr>
  ${summaryHtml}
</table>

<h2>📞 Calls Checklist — Needs Your Attention (${needsCallRows.length})</h2>
<table>
  <tr><th>Done?</th><th>Contact</th><th>Company</th><th>Email</th><th>Phone</th><th>Status</th><th>Replied</th></tr>
  ${callListHtml}
</table>

<h2>⏳ Pending — Awaiting Reply (${pendingRows.length})</h2>
<table>
  <tr><th>Contact</th><th>Company</th><th>Status</th><th>Follow-ups</th><th>Last Email</th></tr>
  ${pendingHtml}
</table>

<hr/>
<p style="color:#888; font-size:12px;">Automated daily report from your Mailing Outreach System</p>
</body>
</html>`;

return [{ json: { html, subject: `📋 Daily Outreach Checklist — ${new Date().toLocaleDateString()} | ${needsCallRows.length} calls pending` } }];
